def is_primary_address(value):
    # Address 0 is a valid primary address (single/unconfigured meter) and
    # 254/255 are the broadcast addresses used by ping and data requests.
    # Rejecting them makes send_ping / request / multi-telegram write nothing.
    try:
        if isinstance(value, (str, bytes, bytearray)):
            value = int(value)
    except (ValueError, TypeError):
        return False

    try:
        return 0x00 <= value <= 0xFF
    except TypeError:
        return False


def is_secondary_address(value):
    if value is None:
        return False

    if not isinstance(value, str):
        return False

    if len(value) != 16:
        return False

    try:
        _ = int(value, 16)
    except ValueError:
        return False

    return True


