def is_primary_address(value):
    try:
        if type(value) == str:
            raw = value.strip()
            # 16-digit strings are secondary addresses. Do not treat them as
            # primary just because the numeric value fits in one byte
            # (including the all-zero secondary address).
            if len(raw) >= 16:
                return False
            value = int(raw, 10)
            if len(raw) > 3 and value == 0:
                return False
    except ValueError:
        return False

    # bool is a subclass of int and False == 0. Address 0 is valid, but
    # False/True are not addresses. Keep the previous True/False results.
    if isinstance(value, bool):
        return 0x00 < value <= 0xFF

    # Integer address 0 is a valid primary address (unconfigured / point to
    # point). Rejecting it made ping, data-request and multi-telegram sends
    # write nothing on the wire.
    if isinstance(value, int):
        return 0x00 <= value <= 0xFF

    return 0x00 < value <= 0xFF


