def inter_byte_timeout(baudrate):
    # EN 13757-2 response window is 330 bit times + 50 ms. The old 300 baud
    # entry (0.12 s) is shorter than a short frame on the wire, so the write
    # was aborted and the meter saw no bytes. 330/300+0.05 == 1.15.
    return {
        300: 1.15,
        600: 0.60,
        1200: 0.4,
        2400: 0.2,
        4800: 0.2,
        9600: 0.1,
        19200: 0.1,
        38400: 0.1,
    }.get(baudrate, None)


_FRAME_SHORT_START = 0x10
_FRAME_LONG_START = 0x68
_FRAME_STOP = 0x16

# C-fields: DIR master->slave is already included in the base masks.
_SND_NKE = 0x40
_REQ_UD1 = 0x5A
_REQ_UD2 = 0x5B
_SND_UD = 0x53
_FCB = 0x20
_SELECT_CI = 0x52
_NETWORK_LAYER_ADDRESS = 0xFD


def _as_address(address):
    if isinstance(address, str):
        address = int(address, 10)
    return int(address) & 0xFF


def serial_send(ser, data):
    """Write raw frame bytes and flush them onto the line.

    Lists (as returned by Telegram.serialize), Telegrams and buffers are all
    accepted. Writing a Telegram object or an uncalled serialize method used
    to hand the port a non-bytes object, which puts nothing on the wire.
    """
    if data is None:
        return 0

    serialize = getattr(data, "serialize", None)
    if callable(serialize) and not isinstance(data, (bytes, bytearray, list)):
        data = serialize()

    if isinstance(data, list):
        data = bytes(bytearray(data))
    elif isinstance(data, bytearray):
        data = bytes(data)
    elif isinstance(data, str):
        data = data.encode("latin1")
    elif not isinstance(data, bytes):
        return 0

    written = ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return written


def _short_frame(c_field, address):
    address = _as_address(address)
    c_field &= 0xFF
    checksum = (c_field + address) & 0xFF
    return bytes((_FRAME_SHORT_START, c_field, address, checksum, _FRAME_STOP))


def send_ping_frame(ser, address):
    """Send SND_NKE (ping / slave reset) as a short frame."""
    serial_send(ser, _short_frame(_SND_NKE, address))


def send_request_frame(ser, address, req=_REQ_UD2):
    """Send REQ_UD2 (or REQ_UD1) to read meter data.

    Primary addresses get one short frame. A 16-digit secondary address is
    selected first, then REQ_UD2 is sent to the network-layer address 0xFD.
    """
    if isinstance(req, str):
        req = int(req, 0)

    if req in (_REQ_UD1, _REQ_UD1 | _FCB):
        c_field = _REQ_UD1 | _FCB
    else:
        # Default and REQ_UD2: FCV is part of 0x5B, FCB selects new data.
        c_field = _REQ_UD2 | _FCB

    if is_secondary_address(address):
        send_select_frame(ser, address)
        serial_send(ser, _short_frame(c_field, _NETWORK_LAYER_ADDRESS))
        return

    serial_send(ser, _short_frame(c_field, address))


def send_request_frame_multi(ser, address):
    """Send REQ_UD2 with FCV and FCB to read the next multi-telegram."""
    serial_send(ser, _short_frame(_REQ_UD2 | _FCB, address))


def send_select_frame(ser, address):
    """Send a secondary-address selection frame (CI = 0x52) to 0xFD."""
    if isinstance(address, str):
        payload = bytearray.fromhex(address)
    else:
        payload = bytearray(address)
    payload.reverse()

    c_field = _SND_UD | _FCB
    body = bytearray((c_field, _NETWORK_LAYER_ADDRESS, _SELECT_CI)) + payload
    length = len(body)
    checksum = sum(body) & 0xFF
    frame = bytes((_FRAME_LONG_START, length, length, _FRAME_LONG_START)) + bytes(body) + bytes((checksum, _FRAME_STOP))
    serial_send(ser, frame)

def is_primary_address(value):
    try:
        if type(value) == str:
            raw = value.strip()
            # 16-digit strings are secondary addresses, even when the
            # numeric value would fit in a single byte (including 0).
            if len(raw) >= 16:
                return False
            value = int(raw, 10)
    except ValueError:
        return False

    # bool is an int subclass and False == 0, but it is not an address.
    # Address 0 itself is valid (unconfigured / point-to-point meter) and
    # must be accepted or ping / REQ_UD2 / multi-telegram write nothing.
    if isinstance(value, bool) or not isinstance(value, int):
        return False

    return 0x00 <= value <= 0xFF


