def inter_byte_timeout(baudrate):
    # 330 bit times + 50 ms (EN 13757-2 / libmbus). 0.12 s at 300 baud is
    # shorter than a 5-byte short frame (5*11/300 = 0.183 s), so the write
    # times out and the meter sees no bytes for ping, REQ_UD2 or multi.
    try:
        baudrate = int(baudrate)
    except (TypeError, ValueError):
        return None

    return {
        300: 1.15,
        600: 0.60,
        1200: 0.4,
        2400: 0.2,
        4800: 0.2,
        9600: 0.1,
        19200: 0.1,
        38400: 0.1,
    }.get(baudrate, None)


