def _serial_send(ser, data):
    if data is None:
        return False

    if isinstance(data, list):
        data = bytearray(data)
    elif isinstance(data, str):
        data = data.encode("latin1")

    ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return True


def _short_frame(c_field, address):
    address = int(address) & 0xFF
    c_field = int(c_field) & 0xFF
    checksum = (c_field + address) & 0xFF
    return bytes((_FRAME_SHORT_START, c_field, address, checksum, _FRAME_STOP))


def _request_c_field(req):
    if req is None:
        req = _REQ_UD2
    if isinstance(req, str):
        req = int(req, 0)
    req = int(req) & 0xFF
    # Base REQ_UD1/REQ_UD2 masks do not include FCB; the master sets it.
    if req in (_REQ_UD1, _REQ_UD2):
        req |= _FCB
    return req


def send_ping_frame(ser, address):
    """Send SND_NKE. Returns False and writes nothing for a bad address."""
    if not is_primary_address(address):
        return False
    return _serial_send(ser, _short_frame(_SND_NKE, address))


def send_request_frame(ser, address, req=None):
    """Send a data request (REQ_UD2 by default).

    Primary address: one short frame.
    Secondary address: selection frame, then REQ_UD2 to 0xFD.
    Invalid address: False, and nothing is written.
    """
    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        return _serial_send(ser, _short_frame(_request_c_field(req), _NETWORK_LAYER_ADDRESS))

    if not is_primary_address(address):
        return False

    return _serial_send(ser, _short_frame(_request_c_field(req), address))


def send_request_frame_multi(ser, address, req=None):
    """Send REQ_UD2 with FCB set, to pull the next multi-telegram."""
    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        return _serial_send(ser, _short_frame(_request_c_field(req), _NETWORK_LAYER_ADDRESS))

    if not is_primary_address(address):
        return False

    return _serial_send(ser, _short_frame(_request_c_field(req), address))


def send_select_frame(ser, address):
    """Select a slave by secondary address (CI 0x52 to address 0xFD).

    The 8-byte address is hex. Only the identification number (first 4
    bytes) is sent little-endian; manufacturer, version and medium follow
    in the order given.
    """
    if not is_secondary_address(address):
        return False

    raw = bytearray.fromhex(address)
    payload = bytearray(reversed(raw[0:4])) + raw[4:8]
    c_field = _SND_UD | _FCB
    body = bytearray((c_field, _NETWORK_LAYER_ADDRESS, _SELECT_CI)) + payload
    length = len(body)
    checksum = sum(body) & 0xFF
    frame = bytes((_FRAME_LONG_START, length, length, _FRAME_LONG_START)) + bytes(body) + bytes((checksum, _FRAME_STOP))
    return _serial_send(ser, frame)

