def _serial_send(ser, data):
    """Push a frame onto the port as real bytes.

    Passing a Telegram, a bare serialize method, or a list of ints makes
    pyserial drop the write, so the meter sees an empty line.
    """
    if data is None:
        return False

    if callable(data) and not isinstance(data, (bytes, bytearray, list)):
        data = data()

    serialize = getattr(data, "serialize", None)
    if callable(serialize) and not isinstance(data, (bytes, bytearray, list)):
        data = serialize()

    if isinstance(data, list):
        data = bytes(bytearray(data))
    elif isinstance(data, bytearray):
        data = bytes(data)
    elif isinstance(data, str):
        data = data.encode("latin1")
    elif not isinstance(data, bytes):
        return False

    if len(data) == 0:
        return False

    ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return True


def _as_int_address(address):
    if isinstance(address, str):
        address = int(address, 10)
    return int(address) & 0xFF


def _short_frame(c_field, address):
    address = _as_int_address(address)
    c_field = int(c_field) & 0xFF
    checksum = (c_field + address) & 0xFF
    return bytes((_SHORT_START, c_field, address, checksum, _FRAME_STOP))


def _request_c_field(req):
    req_ud1 = _lookup_const("REQ_UD1", _REQ_UD1)
    req_ud2 = _lookup_const("REQ_UD2", _REQ_UD2)
    fcb = _lookup_const("CONTROL_MASK_FCB", _FCB)
    if req is None:
        req = req_ud2
    if isinstance(req, str):
        req = int(req, 0)
    req = int(req) & 0xFF
    # Base REQ_UD1/REQ_UD2 masks do not include FCB yet.
    if req in (req_ud1, req_ud2, _REQ_UD1, _REQ_UD2):
        req |= fcb
    return req


def send_ping_frame(ser, address):
    """SND_NKE. False when the address cannot be used, else True."""
    if is_primary_address(address) is False:
        return False
    return _serial_send(ser, _short_frame(_SND_NKE, address))


def send_request_frame(ser, address, req=None):
    """Data request. Secondary addresses are selected, then read via 0xFD."""
    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        return _serial_send(ser, _short_frame(_request_c_field(req), _ADDR_NETWORK))

    if is_primary_address(address) is False:
        return False

    return _serial_send(ser, _short_frame(_request_c_field(req), address))


def send_request_frame_multi(ser, address, req=None):
    """REQ_UD2 with FCB set, asking the slave for the next telegram."""
    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        return _serial_send(ser, _short_frame(_request_c_field(req), _ADDR_NETWORK))

    if is_primary_address(address) is False:
        return False

    return _serial_send(ser, _short_frame(_request_c_field(req), address))


def send_select_frame(ser, address):
    """CI 0x52 selection. Only the 4-byte id is little-endian on the wire."""
    if is_secondary_address(address) is False:
        return False

    raw = bytearray.fromhex(address)
    payload = bytearray(reversed(raw[0:4])) + raw[4:8]
    c_field = _SND_UD | _lookup_const("CONTROL_MASK_FCB", _FCB)
    body = bytearray((c_field, _ADDR_NETWORK, _SELECT_CI)) + payload
    length = len(body)
    checksum = sum(body) & 0xFF
    frame = bytes((_LONG_START, length, length, _LONG_START)) + bytes(body) + bytes((checksum, _FRAME_STOP))
    return _serial_send(ser, frame)

