class _Field:
    def __init__(self, value=None):
        self.parts = [] if value is None else [value]


class _Header:
    def __init__(self, c_field, address, crc):
        self.cField = _Field(c_field)
        self.aField = _Field(address)
        self.crcField = _Field(crc)


class _ShortTelegram:
    """Short frame the caller can update (FCB toggle) and serialize again."""

    def __init__(self, c_field, address):
        address &= 0xFF
        c_field &= 0xFF
        self.header = _Header(c_field, address, (c_field + address) & 0xFF)

    def serialize(self):
