class _Parts:
    def __init__(self, value):
        self.parts = [value & 0xFF]


class _ShortHeader:
    def __init__(self, c_field, address):
        self.cField = _Parts(c_field)
        self.aField = _Parts(address)
        self.crcField = _Parts((c_field + address) & 0xFF)


class _ShortFrame:
    """Short frame whose C-field the caller may toggle (FCB) before resending."""

    def __init__(self, c_field, address):
        self.header = _ShortHeader(c_field & 0xFF, address & 0xFF)

    def serialize(self):
        c_field = self.header.cField.parts[0] & 0xFF
        address = self.header.aField.parts[0] & 0xFF
        # Checksum follows the current C-field, so an FCB toggle stays valid.
        crc = (c_field + address) & 0xFF
        self.header.crcField.parts[0] = crc
        return bytearray((_SHORT_START, c_field, address, crc, _FRAME_STOP))


def _serial_send(ser, data):
    """Write bytes. Lists, strings and Telegram objects never reach the wire."""
    if data is None:
        return False

    serialize = getattr(data, "serialize", None)
    if callable(serialize) and not isinstance(data, (bytes, bytearray, list, str)):
        data = serialize()

    if isinstance(data, list):
        data = bytearray(data)
    elif isinstance(data, str):
        data = bytearray(data, "latin1")
    elif isinstance(data, bytes):
        data = bytearray(data)
    elif not isinstance(data, bytearray):
        return False

    if len(data) == 0:
        return False

    # A short write_timeout drops the frame at low baud and nothing is sent.
    baud = getattr(ser, "baudrate", None)
    try:
        baud = float(baud)
    except (TypeError, ValueError):
        baud = 0.0
    if baud and baud > 0:
        needed = (len(data) * 11.0 / baud) + 0.05
        write_timeout = getattr(ser, "write_timeout", None)
        if isinstance(write_timeout, (int, float)) and write_timeout < needed:
            try:
                ser.write_timeout = needed
            except Exception:
                pass

    ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return True


def _address_byte(address):
    if isinstance(address, str):
        address = int(address, 10)
    return int(address) & 0xFF


def _c_field(req, multi):
    """Normal data request is 0x5B. The next multi-telegram sets FCB (0x7B)."""
    if req is None:
        base = _REQ_UD2
    elif isinstance(req, str):
        base = int(req, 0)
    else:
        base = int(req)
    base &= 0xFF
    if base in (_REQ_UD1, _REQ_UD1 | _FCB, _REQ_UD2, _REQ_UD2 | _FCB):
        base &= ~_FCB
        if multi:
            base |= _FCB
    return base


