    """Send SND_NKE. Returns False and writes nothing for a bad address."""
    if is_primary_address(address) is False:
        return False
    frame = _ShortFrame(_SND_NKE, _address_byte(address))
    if _serial_send(ser, frame.serialize()) is False:
        return False
    return True


def send_request_frame(ser, address, req=None):
    """Send REQ_UD2 (0x5B). Secondary addresses are selected first."""
    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        frame = _ShortFrame(_c_field(req, False), _ADDR_NETWORK)
        if _serial_send(ser, frame.serialize()) is False:
            return False
        return True

    if is_primary_address(address) is False:
        return False

    frame = _ShortFrame(_c_field(req, False), _address_byte(address))
