    return frame


def send_select_frame(ser, address):
    """Select by secondary address. Only the 4-byte id is little-endian."""
    if is_secondary_address(address) is False:
        return False

    raw = bytearray.fromhex(address)
    payload = bytearray(reversed(raw[0:4])) + raw[4:8]
    c_field = _SND_UD | _FCB
    body = bytearray((c_field, _ADDR_NETWORK, _SELECT_CI)) + payload
    length = len(body)
    checksum = sum(body) & 0xFF
    frame = bytearray((_LONG_START, length, length, _LONG_START)) + body + bytearray((checksum, _FRAME_STOP))
    return _serial_send(ser, frame)

def is_primary_address(value):
    try:
        if type(value) == str:
            # 16-digit strings are secondary addresses. int() of an all-zero
            # secondary address is 0 and must not be treated as primary 0.
            if len(value.strip()) >= 16:
                return False
            value = int(value)
    except ValueError:
        return False

    # bool is a subclass of int and False == 0, but it is not an address.
    # Address 0 itself is valid; rejecting it made ping, REQ_UD2 and
    # multi-telegram return before any byte was written. Floats keep the
    # previous comparison.
    if isinstance(value, bool):
        return 0x00 < value <= 0xFF

    if isinstance(value, int):
        return 0x00 <= value <= 0xFF

    return 0x00 < value <= 0xFF


def is_secondary_address(value):
    if value is None:
        return False

    if not isinstance(value, str):
        return False

    if len(value) != 16:
        return False

    try:
        _ = int(value, 16)
    except ValueError:
        return False

    return True


def manufacturer_id(manufacturer):
    if len(manufacturer) != 3:
        return False

    if not manufacturer.isalpha():
        return False

    manufacturer = manufacturer.upper()
    id = ((ord(manufacturer[0]) - 64) * 32 * 32 +
          (ord(manufacturer[1]) - 64) * 32 +
          (ord(manufacturer[2]) - 64))

    if 0x0421 <= id <= 0x6b5a:
        return id

    return False


def manufacturer_encode(value, size):
    if value is None or value is False:
        return None

    data = []
    for i in range(0, size):
        data.append((value >> (i*8)) & 0xFF)

    return data


def inter_byte_timeout(baudrate):
    # EN 13757-2 response window is 330 bit times + 50 ms. At 300 baud the
    # old 0.12 s budget is shorter than a 5-byte short frame
    # (5 * 11 / 300 = 0.183 s), so the write timed out and the line stayed
    # empty for ping, data request and multi-telegram.
    try:
        baudrate = int(baudrate)
    except (TypeError, ValueError):
        return None

    return {
        300: 1.15,
        600: 0.60,
        1200: 0.4,
        2400: 0.2,
        4800: 0.2,
        9600: 0.1,
        19200: 0.1,
        38400: 0.1,
    }.get(baudrate, None)


