def _send_existing(ser, frame):
    """Send a frame the caller already built or whose FCB bit was toggled.

    Checksum is recomputed from the current C and A fields so a toggle of
    CONTROL_MASK_FCB still produces a valid short frame on the wire.
    """
    header = frame.header
    c_field = header.cField.parts[0] & 0xFF
    address = header.aField.parts[0] & 0xFF
    crc = (c_field + address) & 0xFF
    crc_field = getattr(header, "crcField", None)
    crc_parts = getattr(crc_field, "parts", None)
    if isinstance(crc_parts, list):
        if crc_parts:
            crc_parts[0] = crc
        else:
            crc_parts.append(crc)
    return _serial_send(ser, bytes((_SHORT_START, c_field, address, crc, _FRAME_STOP)))


