class _Parts:
    def __init__(self, value):
        self.parts = [value & 0xFF]


class _ShortHeader:
    def __init__(self, c_field, address):
        self.cField = _Parts(c_field)
        self.aField = _Parts(address)
        self.crcField = _Parts((c_field + address) & 0xFF)

    def checksum(self):
        return (self.cField.parts[0] + self.aField.parts[0]) & 0xFF


class _ShortFrame:
    """Short frame. The caller may toggle C-field (FCB) and send it again."""

    def __init__(self, c_field, address):
        self.header = _ShortHeader(c_field & 0xFF, address & 0xFF)

    def serialize(self):
        c_field = self.header.cField.parts[0] & 0xFF
        address = self.header.aField.parts[0] & 0xFF
        crc = (c_field + address) & 0xFF
        self.header.crcField.parts[0] = crc
        return bytearray((_SHORT_START, c_field, address, crc, _FRAME_STOP))


def _is_telegram(obj):
    header = getattr(obj, "header", None)
    if header is None:
        return False
    c_field = getattr(header, "cField", None)
    a_field = getattr(header, "aField", None)
    c_parts = getattr(c_field, "parts", None)
    a_parts = getattr(a_field, "parts", None)
    return (isinstance(c_parts, (list, tuple)) and len(c_parts) > 0 and
            isinstance(a_parts, (list, tuple)) and len(a_parts) > 0)


def _as_wire_bytes(data):
    if data is None:
        return None
    if isinstance(data, str):
        return data.encode("latin1")
    if isinstance(data, bytearray):
        return bytes(data)
    if isinstance(data, bytes):
        return data
    if isinstance(data, list):
        try:
            return bytes(bytearray(data))
        except Exception:
            return None
    return None


def serial_send(ser, data):
    """Write a telegram or raw frame onto the serial port.

    pyserial ignores a Telegram, a bare serialize method, or a list of ints,
    which is why ping / REQ_UD2 / multi-telegram put nothing on the line.
    Short frames are rebuilt from the current C and A fields so an FCB toggle
    keeps a valid checksum.
    """
    if _is_telegram(data):
        header = data.header
        # Long frames (start 0x68) must keep their own body. Short frames are
        # rebuilt so a toggled FCB bit is what actually goes out.
        raw = None
        serialize = getattr(data, "serialize", None)
        if callable(serialize):
            try:
                raw = _as_wire_bytes(serialize())
            except Exception:
                raw = None
        if raw and raw[:1] == bytes((_LONG_START,)):
            data = raw
        else:
            c_field = header.cField.parts[0] & 0xFF
            address = header.aField.parts[0] & 0xFF
            crc = (c_field + address) & 0xFF
            crc_field = getattr(header, "crcField", None)
            crc_parts = getattr(crc_field, "parts", None)
            if isinstance(crc_parts, list):
                if crc_parts:
                    crc_parts[0] = crc
                else:
                    crc_parts.append(crc)
            data = bytes((_SHORT_START, c_field, address, crc, _FRAME_STOP))

    data = _as_wire_bytes(data)
    if not data:
        return False

    baud = getattr(ser, "baudrate", None)
    try:
        baud = float(baud)
    except (TypeError, ValueError):
        baud = 0.0
    if baud and baud > 0:
        needed = (len(data) * 11.0 / baud) + 0.05
        write_timeout = getattr(ser, "write_timeout", None)
        if isinstance(write_timeout, (int, float)) and write_timeout < needed:
            try:
                ser.write_timeout = needed
            except Exception:
                pass

    ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return True


def _address_byte(address):
    if isinstance(address, str):
        address = int(address, 10)
    return int(address) & 0xFF


def _c_field(req, multi):
    """First data request is 0x5B. A multi-telegram read sets FCB (0x7B)."""
    if req is None:
        base = _REQ_UD2
    elif isinstance(req, str):
        base = int(req, 0)
    else:
        base = int(req)
    base &= 0xFF
    if base in (_REQ_UD1, _REQ_UD1 | _FCB, _REQ_UD2, _REQ_UD2 | _FCB):
        base &= ~_FCB
        if multi:
            base |= _FCB
    return base


def _secondary_payload(address):
    """16 hex digits: id and manufacturer little-endian; version and medium as given."""
    raw = bytearray.fromhex(address)
    return (bytearray(reversed(raw[0:4])) +
            bytearray(reversed(raw[4:6])) +
            raw[6:8])


def send_ping_frame(ser, address):
    """Send SND_NKE. Returns False and writes nothing for a bad address."""
    if is_primary_address(address) is False:
        return False
    frame = _ShortFrame(_SND_NKE, _address_byte(address))
    if serial_send(ser, frame) is False:
        return False
    return True


def send_request_frame(ser, address=None, req=None):
    """Send REQ_UD2 (0x5B), or an already-built telegram passed as req.

    ``send_request_frame(ser, req=frame)`` writes that frame. A secondary
    address is selected before the data request. An unusable address with no
    frame returns False and does not touch the line.
    """
    if _is_telegram(address) and req is None:
        req = address
        address = None
    if _is_telegram(req):
        if serial_send(ser, req) is False:
            return False
        return True

    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        frame = _ShortFrame(_c_field(req, False), _ADDR_NETWORK)
        if serial_send(ser, frame) is False:
            return False
        return True

    if is_primary_address(address) is False:
        return False

    frame = _ShortFrame(_c_field(req, False), _address_byte(address))
    if serial_send(ser, frame) is False:
        return False
    return True


def send_request_frame_multi(ser, address=None, req=None):
    """Send REQ_UD2 with FCB (0x7B).

    Returns the frame so the caller can toggle FCB and pass it back via
    ``send_request_frame_multi(ser, req=frame)``.
    """
    if _is_telegram(address) and req is None:
        req = address
        address = None
    if _is_telegram(req):
        if serial_send(ser, req) is False:
            return False
        return req

    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        address = _ADDR_NETWORK
    elif is_primary_address(address) is False:
        return False

    frame = _ShortFrame(_c_field(req, True), _address_byte(address))
    if serial_send(ser, frame) is False:
        return False
    return frame


def send_select_frame(ser, address):
    """CI 0x52 selection to the network-layer address 0xFD."""
    if is_secondary_address(address) is False:
        return False

    payload = _secondary_payload(address)
    c_field = _SND_UD | _FCB
    body = bytearray((c_field, _ADDR_NETWORK, _SELECT_CI)) + payload
    length = len(body)
    checksum = sum(body) & 0xFF
    frame = bytes((_LONG_START, length, length, _LONG_START)) + bytes(body) + bytes((checksum, _FRAME_STOP))
    return serial_send(ser, frame)

def is_primary_address(value):
    try:
        if type(value) == str:
            # 16-digit strings are secondary addresses. int() of an all-zero
            # secondary address is 0 and must not be treated as primary 0.
            if len(value.strip()) >= 16:
                return False
            value = int(value)
    except ValueError:
        return False

    # bool is a subclass of int and False == 0, but it is not an address.
    # Address 0 itself is valid; rejecting it made ping, REQ_UD2 and
    # multi-telegram return before any byte was written. Floats keep the
    # previous comparison.
    if isinstance(value, bool):
        return 0x00 < value <= 0xFF

    if isinstance(value, int):
        return 0x00 <= value <= 0xFF

    return 0x00 < value <= 0xFF


def is_secondary_address(value):
    if value is None:
        return False

    if not isinstance(value, str):
        return False

    if len(value) != 16:
        return False

    try:
        _ = int(value, 16)
    except ValueError:
        return False

    return True


def manufacturer_id(manufacturer):
    if len(manufacturer) != 3:
        return False

    if not manufacturer.isalpha():
        return False

    manufacturer = manufacturer.upper()
    id = ((ord(manufacturer[0]) - 64) * 32 * 32 +
          (ord(manufacturer[1]) - 64) * 32 +
          (ord(manufacturer[2]) - 64))

    if 0x0421 <= id <= 0x6b5a:
        return id

    return False


def manufacturer_encode(value, size):
    if value is None or value is False:
        return None

    data = []
    for i in range(0, size):
        data.append((value >> (i*8)) & 0xFF)

    return data


def inter_byte_timeout(baudrate):
    # EN 13757-2: 330 bit times + 50 ms. At 300 baud 0.12 s is shorter than a
    # 5-byte short frame (5 * 11 / 300 = 0.183 s), so the write was cut off
    # and the meter saw no bytes.
    try:
        baudrate = int(baudrate)
    except (TypeError, ValueError):
        return None

    return {
        300: 1.15,
        600: 0.60,
        1200: 0.4,
        2400: 0.2,
        4800: 0.2,
        9600: 0.1,
        19200: 0.1,
        38400: 0.1,
    }.get(baudrate, None)


_SHORT_START = 0x10
_LONG_START = 0x68
_FRAME_STOP = 0x16
_SND_NKE = 0x40
_REQ_UD1 = 0x5A
_REQ_UD2 = 0x5B
_SND_UD = 0x53
_FCB = 0x20
_SELECT_CI = 0x52
_ADDR_NETWORK = 0xFD


class _Parts:
    def __init__(self, value):
        self.parts = [value & 0xFF]


class _ShortHeader:
    def __init__(self, c_field, address):
        self.cField = _Parts(c_field)
        self.aField = _Parts(address)
        self.crcField = _Parts((c_field + address) & 0xFF)

    def checksum(self):
        return (self.cField.parts[0] + self.aField.parts[0]) & 0xFF


class _ShortFrame:
    """Short frame used if TelegramShort cannot be built.

    The caller may toggle C-field (FCB) and send the same object again.
    """

    def __init__(self, c_field, address):
        self.header = _ShortHeader(c_field & 0xFF, address & 0xFF)

    def serialize(self):
        c_field = self.header.cField.parts[0] & 0xFF
        address = self.header.aField.parts[0] & 0xFF
        crc = (c_field + address) & 0xFF
        self.header.crcField.parts[0] = crc
        return bytearray((_SHORT_START, c_field, address, crc, _FRAME_STOP))


def _is_telegram(obj):
    header = getattr(obj, "header", None)
    if header is None:
        return False
    c_field = getattr(header, "cField", None)
    a_field = getattr(header, "aField", None)
    c_parts = getattr(c_field, "parts", None)
    a_parts = getattr(a_field, "parts", None)
    return (isinstance(c_parts, (list, tuple)) and len(c_parts) > 0 and
            isinstance(a_parts, (list, tuple)) and len(a_parts) > 0)


def _as_wire_bytes(data):
    if data is None:
        return None
    if isinstance(data, str):
        return data.encode("latin1")
    if isinstance(data, bytearray):
        return bytes(data)
    if isinstance(data, bytes):
        return data
    if isinstance(data, list):
        try:
            return bytes(bytearray(data))
        except Exception:
            return None
    return None


def _make_short(c_field, address):
    """Build a short telegram. Prefer the library class so callers can toggle FCB."""
    c_field &= 0xFF
    address &= 0xFF
    telegram_short = None
    try:
        from meterbus.telegram_short import TelegramShort
        telegram_short = TelegramShort
    except Exception:
        try:
            import meterbus
            telegram_short = getattr(meterbus, "TelegramShort", None)
        except Exception:
            telegram_short = None

    if telegram_short is not None:
        try:
            frame = telegram_short()
            frame.header.cField.parts = [c_field]
            frame.header.aField.parts = [address]
            if (frame.header.cField.parts and
                    frame.header.cField.parts[0] == c_field and
                    frame.header.aField.parts and
                    frame.header.aField.parts[0] == address):
                return frame
        except Exception:
            pass
    return _ShortFrame(c_field, address)


def serial_send(ser, data):
    """Write a telegram or raw frame onto the serial port.

    pyserial drops a Telegram, a bare serialize method, or a list of ints,
    which is why ping / REQ_UD2 / multi-telegram put nothing on the line.
    Short frames are rebuilt from the current C and A fields so an FCB toggle
    keeps a valid checksum.
    """
    if _is_telegram(data):
        header = data.header
        raw = None
        serialize = getattr(data, "serialize", None)
        if callable(serialize):
            try:
                raw = _as_wire_bytes(serialize())
            except Exception:
                raw = None
        if raw and raw[:1] == bytes((_LONG_START,)):
            data = raw
        else:
            c_field = header.cField.parts[0] & 0xFF
            address = header.aField.parts[0] & 0xFF
            crc = (c_field + address) & 0xFF
            crc_field = getattr(header, "crcField", None)
            crc_parts = getattr(crc_field, "parts", None)
            if isinstance(crc_parts, list):
                if crc_parts:
                    crc_parts[0] = crc
                else:
                    crc_parts.append(crc)
            data = bytes((_SHORT_START, c_field, address, crc, _FRAME_STOP))

    data = _as_wire_bytes(data)
    if not data:
        return False

    baud = getattr(ser, "baudrate", None)
    try:
        baud = float(baud)
    except (TypeError, ValueError):
        baud = 0.0
    if baud and baud > 0:
        needed = (len(data) * 11.0 / baud) + 0.05
        write_timeout = getattr(ser, "write_timeout", None)
        if isinstance(write_timeout, (int, float)) and write_timeout < needed:
            try:
                ser.write_timeout = needed
            except Exception:
                pass

    ser.write(data)
    flush = getattr(ser, "flush", None)
    if callable(flush):
        try:
            flush()
        except Exception:
            pass
    return True


def _address_byte(address):
    if isinstance(address, str):
        address = int(address, 10)
    return int(address) & 0xFF


def _c_field(req, multi):
    """First data request is 0x5B. A multi-telegram read sets FCB (0x7B)."""
    if req is None:
        base = _REQ_UD2
    elif isinstance(req, str):
        base = int(req, 0)
    else:
        base = int(req)
    base &= 0xFF
    if base in (_REQ_UD1, _REQ_UD1 | _FCB, _REQ_UD2, _REQ_UD2 | _FCB):
        base &= ~_FCB
        if multi:
            base |= _FCB
    return base


def _secondary_payload(address):
