        if serial_send(ser, req) is False:
            return False
        return True

    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        frame = _make_short(_c_field(req, False), _ADDR_NETWORK)
        if serial_send(ser, frame) is False:
            return False
        return True

    if is_primary_address(address) is False:
        return False

    frame = _make_short(_c_field(req, False), _address_byte(address))
