def send_request_frame_multi(ser, address=None, req=None):
    """Send REQ_UD2 with FCB (0x7B).

    Returns the frame so the caller can toggle FCB and pass it back via
    ``send_request_frame_multi(ser, req=frame)``.
    """
    if _is_telegram(address) and req is None:
        req = address
        address = None
    if _is_telegram(req):
        if serial_send(ser, req) is False:
            return False
        return req

    if is_secondary_address(address):
        if send_select_frame(ser, address) is False:
            return False
        address = _ADDR_NETWORK
    elif is_primary_address(address) is False:
        return False

